const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw :
JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

const clientes = $input.first().json.body?.clientes || $input.first().json.clientes || [];
const investimentos = $input.first().json.investimentos || [];

// Função para escolher uma mensagem aleatória
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

const resultados = clientes.map(c => {
  const nome = c.nome;
  const email = c.email;
  const perfil = c.perfil;

  // Extrai apenas os números e converte o saldo para float
  const saldoNum = Number(c.saldo.replace(/[^\d,]/g, '').replace(',', '.'));

  // Encontra o investimento compatível com o perfil
  const recomendacoes = investimentos.filter(inv => inv.perfil === perfil);
  const escolhido = recomendacoes.length > 0 ? recomendacoes[0] : null;

  let motivo = "";
  let mensagens = [];

  if (escolhido) {
    if (saldoNum >= escolhido.minimo) {
      motivo = "saldo_ok";
      mensagens = [
        `Olá ${nome}! Pelo seu perfil (${perfil}), uma boa opção é **${escolhido.produto}** (mínimo R$ ${escolhido.minimo}). Com seu saldo atual (${c.saldo}), você já consegue investir. Rentabilidade: ${escolhido.rentabilidade}.`,
        `Oi ${nome}! Recomendação para perfil ${perfil}: **${escolhido.produto}** (mínimo R$ ${escolhido.minimo}). Seu saldo (${c.saldo}) já atende o mínimo. Rentabilidade: ${escolhido.rentabilidade}.`,
        `${nome}, indo direto ao ponto: para o perfil ${perfil}, **${escolhido.produto}** (mínimo R$ ${escolhido.minimo}). Você tem ${c.saldo}, então dá pra aplicar. Rentabilidade: ${escolhido.rentabilidade}.`
      ];
    } else {
      motivo = "saldo_insuficiente";
      mensagens = [
        `Olá ${nome}. Seu perfil é ${perfil} e indicamos **${escolhido.produto}**. Porém, o aporte mínimo é R$ ${escolhido.minimo} e seu saldo atual é ${c.saldo}. Continue poupando! Rentabilidade: ${escolhido.rentabilidade}.`,
        `Oi ${nome}! Para investir em **${escolhido.produto}** (ideal para o perfil ${perfil}), você precisa de pelo menos R$ ${escolhido.minimo}. Seu saldo atual é ${c.saldo}. Rentabilidade esperada: ${escolhido.rentabilidade}.`
      ];
    }
  }

  return {
    nome,
    email,
    perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: mensagens.length > 0 ? pick(mensagens) : "Nenhuma recomendação."
  };
});

// Retorna a estrutura unificada conforme exigido
return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];

// Pega o array de resultados consolidado no nó anterior
const resultados = $input.first().json.resultados || [];

// Transforma o array em múltiplos itens independentes para o n8n (10 items)
const items = resultados.map(c => {

  // Constrói a mensagem base de contexto para orientar o LLM
  let mensagem_base = "";
  if (c.motivo === "saldo_ok") {
    mensagem_base = `${c.nome}, indo direto ao ponto: para o perfil ${c.perfil}, **${c.recomendacao.produto}** (mínimo R$ ${c.recomendacao.minimo}). Você tem ${c.saldo_texto}, então dá pra aplicar. Rentabilidade: ${c.recomendacao.rentabilidade}.`;
  } else {
    mensagem_base = `${c.nome}, para o perfil ${c.perfil}, indicamos **${c.recomendacao.produto}**. O aporte mínimo é R$ ${c.recomendacao.minimo}, e seu saldo atual é ${c.saldo_texto}. Rentabilidade: ${c.recomendacao.rentabilidade}.`;
  }

  return {
    json: {
      email_to: c.email,
      nome: c.nome,
      perfil: c.perfil,
      saldo_texto: c.saldo_texto,
      saldo_num: c.saldo_num,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: mensagem_base,
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: [
          "promessas de ganho",
          "garantias",
          "linguagem agressiva"
        ]
      }
    }
  };
});

return items;

