const llmOutputs = $input.all();
// Recupera os dados originais do nó 'Trata LLM' (nome, email_to, recomendação, etc.)
const dadosOriginais = $('Trata LLM').all();

return llmOutputs.map((item, index) => {
  const original = dadosOriginais[index].json;
  let jsonLLM = {};

  try {
    // O nó "AI Agent" envia a resposta gerada dentro da propriedade 'output'
    let rawText = item.json.output || "";

    // Limpa a formatação markdown (```json ... ```) caso o modelo a inclua acidentalmente
    rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

    jsonLLM = JSON.parse(rawText);
  } catch (error) {
    jsonLLM = {
      subject: "Erro de processamento",
      text_body: "Não foi possível extrair o JSON do LLM.",
      html_body: "<p>Não foi possível extrair o JSON do LLM.</p>"
    };
  }

  return {
    json: {
      ok: true,
      to: original.email_to,
      subject: jsonLLM.subject,
      text_body: jsonLLM.text_body,
      html_body: jsonLLM.html_body,
      // Opcional: mantém alguns campos úteis na chave 'meta' para debug ou uso futuro
      meta: {
        nome: original.nome,
        perfil: original.perfil,
        produto: original.recomendacao?.produto,
        minimo: original.recomendacao?.minimo,
        rentabilidade: original.recomendacao?.rentabilidade,
        motivo: original.motivo
      }
    }
  };
});

